// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.fin;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FinalizeDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        // CORRECT: try-with-resources closes the session deterministically,
        // exactly when the block ends, even if an exception is thrown.
        try (LedgerSession session = new LedgerSession("month-end")) {
            session.transfer(rajesh, priya, new BigDecimal("50000"));
        } // close() runs HERE, guaranteed

        log.info(() -> "Rajesh Rs." + rajesh.getBalance() + ", Priya Rs." + priya.getBalance());

        // ANTI-PATTERN: relying on finalize() for cleanup (do NOT do this).
        LegacyLedgerSession legacy = new LegacyLedgerSession("legacy");
        legacy = null; // dropping the reference does NOT promptly close anything
        log.warning(() -> "LegacyLedgerSession relies on finalize → close timing NOT guaranteed");
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in LedgerSession.java (CORRECT: AutoCloseable) ───
class LedgerSession implements AutoCloseable {
    private static final Logger log = Logger.getLogger("BankLog");
    private final String name;

    LedgerSession(String name) {
        this.name = name;
        log.info(() -> "Ledger session OPEN: " + name); // acquire resource
    }

    void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "Transferred Rs." + amount + " within session " + name);
    }

    @Override
    public void close() {
        // Deterministic cleanup: runs exactly when try-with-resources ends.
        log.info(() -> "Ledger session CLOSED deterministically: " + name);
    }
}

// ─── Would be in LegacyLedgerSession.java (ANTI-PATTERN: finalize) ───
class LegacyLedgerSession {
    private static final Logger log = Logger.getLogger("BankLog");
    private final String name;

    LegacyLedgerSession(String name) {
        this.name = name;
        log.info(() -> "Legacy session OPEN: " + name);
    }

    // Deprecated since Java 9. Timing is NOT guaranteed; may never run.
    @Override
    @SuppressWarnings("removal")
    protected void finalize() {
        // Could leak the resource for a long time, or forever, under load.
        log.warning(() -> "finalize() ran (eventually, maybe) for: " + name);
    }
}
